#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
#include <vector>
#include <chrono>
#include <algorithm>
#include "native_kernels.inc"
int main(){const int P=4096,F=16,G=16,W=P*F+2*G;const unsigned guard=0xA55A3CC3u;std::vector<unsigned> srcfixture(2*P*F),dstfixture(2*P*F);FILE*f=fopen("fixture_source_aos_u32.bin","rb");if(!f)return 2;fread(srcfixture.data(),4,srcfixture.size(),f);fclose(f);f=fopen("fixture_initial_aos_u32.bin","rb");if(!f)return 3;fread(dstfixture.data(),4,dstfixture.size(),f);fclose(f);std::vector<unsigned>s(W),d(W),sourceback(W),initialback(W),out(W);unsigned *ds,*dd;cudaMalloc(&ds,W*4);cudaMalloc(&dd,W*4);auto launch=[&](int layout,int n){if(layout==0)add_kernel_interleaved<<<(n+255)/256,256>>>((INTERLEAVED_T*)(dd+G),(const INTERLEAVED_T*)(ds+G),n);else add_kernel_non_interleaved<<<(n+255)/256,256>>>((NON_INTERLEAVED_T*)(dd+G),(const NON_INTERLEAVED_T*)(ds+G),n);return cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;};auto prepare=[&](int fixture,int layout){std::fill(s.begin(),s.end(),guard);std::fill(d.begin(),d.end(),guard);for(int i=0;i<P;i++)for(int k=0;k<F;k++){int index=G+(layout==0?i*F+k:k*P+i);s[index]=srcfixture[fixture*P*F+i*F+k];d[index]=dstfixture[fixture*P*F+i*F+k];}return cudaMemcpy(ds,s.data(),W*4,cudaMemcpyHostToDevice)==cudaSuccess&&cudaMemcpy(dd,d.data(),W*4,cudaMemcpyHostToDevice)==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;};for(int l=0;l<2;l++){if(!prepare(0,l)||!launch(l,P))return 4;}bool all=true;
 for(int trial=1;trial<=5;trial++){bool ok=true;int bad=0;std::vector<unsigned>prefix,outputs;double times[8];int path_index=0;
  for(int fixture=0;fixture<2;fixture++)for(int shape=0;shape<2;shape++)for(int layout=0;layout<2;layout++){int n=shape?4093:4096;ok &=prepare(fixture,layout);ok &=cudaMemcpy(initialback.data(),dd,W*4,cudaMemcpyDeviceToHost)==cudaSuccess;ok &=initialback==d;auto start=std::chrono::steady_clock::now();ok &=launch(layout,n);times[path_index++]=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();ok &=cudaMemcpy(sourceback.data(),ds,W*4,cudaMemcpyDeviceToHost)==cudaSuccess;ok &=sourceback==s;ok &=cudaMemcpy(out.data(),dd,W*4,cudaMemcpyDeviceToHost)==cudaSuccess;for(int i=0;i<G;i++)bad+=out[i]!=guard||out[W-G+i]!=guard;
   for(int i=0;i<P;i++)for(int k=0;k<F;k++){int index=G+(layout==0?i*F+k:k*P+i);unsigned expected=dstfixture[fixture*P*F+i*F+k]+(i<n?4096u*srcfixture[fixture*P*F+i*F+k]:0u);bad+=out[index]!=expected;}prefix.insert(prefix.end(),sourceback.begin(),sourceback.end());prefix.insert(prefix.end(),initialback.begin(),initialback.end());outputs.insert(outputs.end(),out.begin(),out.end());
  }ok &=bad==0;all &=ok;std::vector<unsigned>artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());char path[80];snprintf(path,80,"output_trial%d.bin",trial);f=fopen(path,"wb");if(!f)return 5;fwrite(artifact.data(),4,artifact.size(),f);fclose(f);double total=0;for(double v:times)total+=v;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"sum8_separate_layout_kernel_hostwindows\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,total,ok?"true":"false",artifact.size(),bad?1:0);for(int j=0;j<8;j++)printf("%s%.12g",j?",":"",times[j]);printf("],\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path,artifact.size());
 }cudaFree(ds);cudaFree(dd);puts(all?"PASS":"FAIL");return all?0:1;}
